function pcc(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}global $wpdb;$prefix=$wpdb->prefix.Config::TABLE_PREFIX;$nonce=bin2hex(random_bytes(5));$terms=[];$dir=sys_get_temp_dir().DIRECTORY_SEPARATOR.'va-product-race-'.$nonce;$processes=[];
try{$cat=wp_insert_term('Race Cat '.$nonce,'product_cat');pcc(!is_wp_error($cat),'Categoría race.');$terms[]=['product_cat',(int)$cat['term_id']];$row=['line'=>2,'sku'=>'RACE-'.$nonce,'name'=>'Producto concurrente','category'=>'Race Cat '.$nonce,'subcategory'=>'','brand'=>'','unit'=>'','description'=>'','status'=>'draft','image'=>''];pcc(mkdir($dir,0700),'Directorio race.');$barrier=$dir.DIRECTORY_SEPARATOR.'go';$worker=__DIR__.'/product-bulk-concurrency-worker.php';$desc=[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']];for($i=0;$i<2;$i++){$ready=$dir.DIRECTORY_SEPARATOR.'ready-'.$i;$pipes=[];$proc=proc_open([PHP_BINARY,$worker,base64_encode(json_encode($row,JSON_THROW_ON_ERROR)),$barrier,$ready],$desc,$pipes);pcc(is_resource($proc),'Worker race.');fclose($pipes[0]);$processes[]=['process'=>$proc,'pipes'=>$pipes,'ready'=>$ready];}$deadline=microtime(true)+15;do{$readyCount=count(array_filter($processes,fn($p)=>is_file($p['ready'])));if($readyCount===2)break;usleep(10000);clearstatcache();}while(microtime(true)<$deadline);pcc($readyCount===2,'Workers sin barrera.');touch($barrier);$results=[];foreach($processes as&$p){$out=trim(stream_get_contents($p['pipes'][1]));$err=trim(stream_get_contents($p['pipes'][2]));fclose($p['pipes'][1]);fclose($p['pipes'][2]);$exit=proc_close($p['process']);$p['process']=null;pcc($exit===0,'Worker falló.');pcc($err===''||str_contains($err,'Deadlock found'),'Worker emitió error inesperado.');$results[]=json_decode($out,true,16,JSON_THROW_ON_ERROR);}unset($p);pcc(count(array_filter($results,fn($r)=>$r['status']==='won'))===1&&count(array_filter($results,fn($r)=>$r['status']==='lost'&&$r['message']==='safe'))===1,'Carrera sin ganador único/respuesta segura.');pcc((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$prefix}products WHERE sku=%s",$row['sku']))===1,'Carrera duplicó SKU.');echo "product-bulk-concurrency-test: PASS winner=1 loser=1 duplicates=0\n";
}finally{foreach($processes as$p){if(is_resource($p['process'])){proc_terminate($p['process']);proc_close($p['process']);}foreach($p['pipes']as$pipe)if(is_resource($pipe))fclose($pipe);if(is_file($p['ready']))unlink($p['ready']);}if(isset($barrier)&&is_file($barrier))unlink($barrier);if(is_dir($dir))rmdir($dir);if(isset($row))$wpdb->delete($prefix.'products',['sku'=>$row['sku']]);foreach(array_reverse($terms)as[$tax,$id])wp_delete_term($id,$tax);}
